 AS x(training_no integer,question_no integer,question text,options jsonb,
      correct_index integer,source_time text)
)
INSERT INTO public.basic_training_questions(training_no,question_no,question,options,correct_index,source_time)
SELECT training_no,question_no,question,options,correct_index,source_time FROM rows
ON CONFLICT(training_no,question_no) DO UPDATE
SET question=EXCLUDED.question,options=EXCLUDED.options,correct_index=EXCLUDED.correct_index,
 source_time=EXCLUDED.source_time;

DO $verify$
DECLARE v_count integer;
BEGIN
 SELECT count(*) INTO v_count FROM public.basic_training_questions WHERE training_no BETWEEN 1 AND 8;
 IF v_count<>160 THEN
   RAISE EXCEPTION 'Expected 160 approved basic-training questions; found %',v_count;
 END IF;
END $verify$;
COMMIT;
